function F({registerIndicator:p,sourceValues:k,nulls:y}){p({id:"oa-ehlers-distance-coefficient-filter",name:"Ehlers Distance Coefficient Filter (EDCF)",category:"Moving Averages",placement:"onchart",inputs:[{key:"length",type:"number",label:"Length",default:14,min:2,max:500,step:1,tooltip:"Window size. The filter needs twice this many bars less two before it can report a value."},{key:"source",type:"source",label:"Source",default:"hl2"}],plots:[{key:"dcf",type:"line",title:"EDCF",style:{color:"#6d1e7f",lineWidth:2}}],calc(c,s){const n=Math.max(2,Math.min(500,Math.floor(Number(s.length)||14))),f=k(c,s.source??"hl2"),u=c.length,h=new Array(u).fill(NaN),g=2*(n-1);for(let e=g;e<u;e++){let m=0,t=0,i=!0;for(let l=0;l<n;l++){const o=f[e-l];if(!Number.isFinite(o)){i=!1;break}let r=0;for(let a=1;a<n;a++){const b=f[e-l-a];if(!Number.isFinite(b)){i=!1;break}const d=o-b;r+=d*d}if(!i)break;m+=r*o,t+=r}i&&Number.isFinite(t)&&t!==0&&(h[e]=m/t)}return{dcf:y(h)}}})}export{F as default};
